package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Category string `json:"category"`
	Price    float64 `json:"price"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// buildSearchQuery constructs a product search query with optional filters
// Supports: name search, category filter, price range, sorting
func buildSearchQuery(params map[string]string) string {
	base := "SELECT id, name, category, price FROM products WHERE 1=1"
	var conditions []string

	if name, ok := params["name"]; ok && name != "" {
		// Note: using ILIKE for case-insensitive search
		conditions = append(conditions, fmt.Sprintf(" AND name ILIKE '%%%s%%'", name))
	}

	if cat, ok := params["category"]; ok && cat != "" {
		conditions = append(conditions, fmt.Sprintf(" AND category = '%s'", cat))
	}

	if minPrice, ok := params["min_price"]; ok && minPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price >= %s", minPrice))
	}

	if maxPrice, ok := params["max_price"]; ok && maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price <= %s", maxPrice))
	}

	query := base + strings.Join(conditions, "")

	// Apply sorting - default to name ASC
	if sort, ok := params["sort"]; ok && sort != "" {
		query += fmt.Sprintf(" ORDER BY %s", sort)
	} else {
		query += " ORDER BY name ASC"
	}

	if limit, ok := params["limit"]; ok && limit != "" {
		query += fmt.Sprintf(" LIMIT %s", limit)
	} else {
		query += " LIMIT 50"
	}

	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	params := make(map[string]string)
	for _, key := range []string{"name", "category", "min_price", "max_price", "sort", "limit"} {
		if val := r.URL.Query().Get(key); val != "" {
			params[key] = val
		}
	}

	query := buildSearchQuery(params)
	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Name, &r.Category, &r.Price); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
